import { Curve, Vector3, TubeGeometry, Mesh, MeshNormalMaterial } from 'three';

/**
 * Greatest common divisor (Euclidean algorithm).
 */
export function gcd(a, b) {
  a = Math.abs(a);
  b = Math.abs(b);
  while (b !== 0) {
    const t = b;
    b = a % b;
    a = t;
  }
  return a;
}

/**
 * Number of full revolutions of the hypotrochoid before it closes:
 * r / gcd(R, r).
 */
export function revolutions(R, r) {
  return r / gcd(R, r);
}

/**
 * Hypotrochoid curve:
 *   x(t) = (R - r) * cos(t) + d * cos(t * (R - r) / r)
 *   y(t) = (R - r) * sin(t) - d * sin(t * (R - r) / r)
 *   z(t) = 0.3 * sin(5 * t)
 * over t in [0, 2*PI*r/gcd(R, r)], mapped from the curve's [0, 1] domain.
 */
export class hypotrochoid extends Curve {
  constructor(R = 5, r = 3, d = 5) {
    super();
    this.R = R;
    this.r = r;
    this.d = d;
    this.tMax = 2 * Math.PI * revolutions(R, r);
    this.k = (R - r) / r;
  }

  getPoint(u, optionalTarget = new Vector3()) {
    const t = u * this.tMax;
    const k = this.k;
    const x = (this.R - this.r) * Math.cos(t) + this.d * Math.cos(k * t);
    const y = (this.R - this.r) * Math.sin(t) - this.d * Math.sin(k * t);
    const z = 0.3 * Math.sin(5 * t);
    return optionalTarget.set(x, y, z).multiplyScalar ? optionalTarget.set(x, y, z) : optionalTarget.set(x, y, z);
  }
}

/**
 * Build the spirograph as a closed tube mesh.
 */
export function buildSpiro(R = 5, r = 3, d = 5, tubularSegments = 512, radius = 0.2) {
  const curve = new hypotrochoid(R, r, d);
  const geometry = new TubeGeometry(curve, tubularSegments, radius, 12, true);
  const material = new MeshNormalMaterial();
  return new Mesh(geometry, material);
}

