import { describe, it, expect } from 'vitest';
import { hypotrochoid, gcd, revolutions, buildSpiro } from '../src/spiro.js';

describe('gcd', () => {
  it('works on (105, 25)', () => {
    expect(gcd(105, 25)).toBe(5);
  });

  it('handles coprime and trivial inputs', () => {
    expect(gcd(5, 3)).toBe(1);
    expect(gcd(12, 12)).toBe(12);
    expect(gcd(0, 7)).toBe(7);
  });
});

describe('revolutions', () => {
  it('returns r / gcd(R, r)', () => {
    expect(revolutions(5, 3)).toBe(3); // gcd 1
    expect(revolutions(105, 25)).toBe(5); // gcd 5
  });
});

describe('hypotrochoid closure', () => {
  it('closes: getPoint(0) equals getPoint(1) within 1e-6 for (5, 3, 5)', () => {
    const curve = new hypotrochoid(5, 3, 5);
    const p0 = curve.getPoint(0);
    const p1 = curve.getPoint(1);
    expect(Math.abs(p0.x - p1.x)).toBeLessThanOrEqual(1e-6);
    expect(Math.abs(p0.y - p1.y)).toBeLessThanOrEqual(1e-6);
    expect(Math.abs(p0.z - p1.z)).toBeLessThanOrEqual(1e-6);
  });

  it('parameter span is 2*PI*r/gcd(R, r) = 6*PI for (5, 3, 5)', () => {
    const curve = new hypotrochoid(5, 3, 5);
    expect(curve.tMax).toBeCloseTo(2 * Math.PI * revolutions(5, 3), 12);
    // gcd(5,3) === 1, so span must be exactly 2*PI*3
    expect(curve.tMax).toBeCloseTo(2 * Math.PI * 3, 12);
  });
});

describe('planar radius bound', () => {
  it('max planar radius never exceeds R - r + d + 1e-9 over 2000 samples', () => {
    const cases = [
      [5, 3, 5],
      [7, 4, 6],
      [8, 5, 10],
      [13, 7, 2],
    ];
    for (const [R, r, d] of cases) {
      const curve = new hypotrochoid(R, r, d);
      let maxR = 0;
      for (let i = 0; i < 2000; i++) {
        const p = curve.getPoint(i / 2000);
        maxR = Math.max(maxR, Math.hypot(p.x, p.y));
      }
      expect(maxR).toBeLessThanOrEqual(R - r + d + 1e-9);
    }
  });
});

describe('d changes the shape', () => {
  it('different d values change the sampled polyline', () => {
    const a = new hypotrochoid(5, 3, 5);
    const b = new hypotrochoid(5, 3, 7);
    let differs = false;
    for (let i = 1; i < 100; i++) {
      const pa = a.getPoint(i / 100);
      const pb = b.getPoint(i / 100);
      if (pa.distanceTo(pb) > 1e-9) {
        differs = true;
        break;
      }
    }
    expect(differs).toBe(true);
  });
});

describe('buildSpiro', () => {
  it('returns a mesh with a closed TubeGeometry', () => {
    const mesh = buildSpiro(5, 3, 5);
    expect(mesh.isMesh).toBe(true);
    expect(mesh.geometry.type).toBe('TubeGeometry');
    expect(mesh.geometry.closed).toBe(true);
  });
});

